def value_iteration(mdp, gamma, eps):
    V = {s: 0.0 for s in mdp.states}
    while True:
        delta = 0.0
        for s in mdp.states:
            best = max(
                mdp.R(s, a)
                + gamma * sum(p * V[s2] for s2, p in mdp.T(s, a))
                for a in mdp.actions(s)
            )
            delta = max(delta, abs(best - V[s]))
            V[s] = best
        if delta < eps:
            return V
